// src/index.js (frontend)
import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import { createBrowserRouter, RouterProvider } from "react-router-dom";
import Feed from "./pages/Feed"; // your Feed page
// import "./index.css"; // optional global styles

// ✅ React Router v7 future flags (frontend only)
window.__react_router_future__ = {
  v7_startTransition: true,
  v7_relativeSplatPath: true
};

// Define routes
const router = createBrowserRouter([
  { path: "/", element: <App /> },
  { path: "/feed", element: <Feed /> }, // feed page route
  { path: "*", element: <div>404 Not Found</div> } // catch-all
]);

// Render app
ReactDOM.createRoot(document.getElementById("root")).render(
  <React.StrictMode>
    <RouterProvider router={router} />
  </React.StrictMode>
);
